Matching Ayahs
- = අලිෆ්, ලාම්, මීම්. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = ඔවුන් තම දෙවියන්ගේ පැත්තෙන් යහමගෙහි සිටින්නෝය. ඔවුන්ම සාර්ථක වන්නෝය. 2:5; 31:5
- = ඊශ්‍රායෙල් දරුවෙනි, මා ඔබලාට කළ අනුග්‍රහය හා මා ඔබලා ලෝකවාසීන්ට වඩා උසස් කළ බව සිහි කරන්න. 2:47; 2:122
- = එය පහ වී ගිය ජනතාවකි. ඔවුන්ට ඔවුන් උපයා ගත් දේ හිමි වේ. තවද ඔබලාට ඔබලා උපයා ගත් දේ හිමි වේ. තවද ඔවුන් කරමින් සිටි දේ ගැන ඔබලාගෙන් විමසනු නොලැබේ. 2:134; 2:141
- = ඔවුන් එහි සදාකාලිකව වාසය කරන්නෝය. ඔවුන්ගේ දඬුවම සැහැල්ලු නොකරනු ලැබේ. තවද ඔවුන්ට විවේකයක් ද නොදෙනු ලැබේ. 2:162; 3:88
- = එහෙත් ඉන්පසුව පසුතැවිලි වී තමන් වහන්සේ ප්‍රතිසංස්කරණය කර ගත් අය හැර. නියත වශයෙන්ම අල්ලාහ් ඉමහත් ක්ෂමාශීලී හා අති දයාන්විතය. 3:89; 24:5
- = තවද ප්‍රතික්ෂේප කර අපගේ වදන් ප්‍රතික්ෂේප කළ අය – ඔවුන්ම නිරයේ වාසීන්ය. 5:10; 5:86
- = තවද ඔවුන්ගේ දෙවියන්ගේ සංඥාවන්ගෙන් කිසිදු සංඥාවක් ඔවුන් වෙත පැමිණියේ නැත. නමුත් ඔවුන් ඉන් ඉවතට හැරී ගියහ. 6:4; 36:46
- = තවද නුඹට පෙර දූතයින් හාස්‍යයට ලක් කරනු ලැබ ඇත. එහෙත් ඔවුන්ට හාස්‍යය කළ අයව ඔවුන් හාස්‍යය කළ දේම වට කර ගත්තේය. 6:10; 21:41
- = පවසනු: "මම මාගේ දෙවියන්ට අකීකරු වුව හොත්, භයංකර දිනයේ දඬුවමට මම බිය වෙමි." 6:15; 39:13
- = එවිට භූමිකම්පාව ඔවුන් අල්ලා ගත්තේය. එවිට ඔවුන් තම නිවෙස් තුළ බිම ඇද වැටී සිටියහ. 7:78; 7:91
- = එවිට ඔහු තම සැරයටිය විසි කළේය. එකෙණෙහිම එය පැහැදිලි සර්පයෙක් විය. 7:107; 26:32
- = තවද ඔහු තම අත එළියට ගත්තේය. එකෙණෙහිම එය බලන්නන්ට සුදු (බැබළෙන) විය. 7:108; 26:33
- = ඔවුහු පැවසූහ: "අපි ලෝකවාසීන්ගේ දෙවියන් වහන්සේ ගැන විශ්වාස කළෙමු." 7:121; 26:47
- = මූසා සහ හාරූන්ගේ දෙවියන්. 7:122; 26:48
- = තවද මම ඔවුන්ට කල් දෙන්නෙමි. නියත වශයෙන්ම මාගේ උපාය ස්ථිරය. 7:183; 68:45
- = ඔහුම තම දූතයා යහමග හා සත්‍ය ආගම සමඟ එව්වේය. එය සියලු ආගම්වලට වඩා ඉහළ නැංවීම සඳහාය. බහුදේවවාදීන් එයට අකමැති වුවද. 9:33; 61:9
- = නබිතුමනි, ප්‍රතික්ෂේප කරන්නන් හා කුහකයින් සමඟ සටන් කරනු. තවද ඔවුන් කෙරෙහි දැඩි වනු. ඔවුන්ගේ රැකවරණය නිරයයි. එම ගමනාන්තය කෙතරම් නරකද! 9:73; 66:9
- = තවද ඔවුහු මෙසේ පවසති: "මෙම පොරොන්දුව කවදාද? නුඹලා සත්‍යවාදීන් නම්?" 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = තවද නියත වශයෙන්ම අපි මූසා අපගේ සංඥා හා පැහැදිලි බලය සමඟ එව්වෙමු. 11:96; 40:23
- = තවද නියත වශයෙන්ම අපි මූසාට ග්‍රන්ථය ලබා දුන්නෙමු. නමුත් එය සම්බන්ධයෙන් මතභේද ඇති විය. තවද නුඹගේ දෙවියන්ගෙන් පූර්ව වචනයක් නොතිබුනේ නම්, ඔවුන් අතර විනිශ්චය කරනු ලැබ තිබිණි. තවද නියත වශයෙන්ම ඔවුහු එය සම්බන්ධයෙන් සැකයෙහි සිටිති. 11:110; 41:45
- = එය අල්ලාහ්ට අපහසු නොවේ. 14:20; 35:17
- = "මම ඔහුව හැඩ ගන්වා මාගේ ආත්මයෙන් ඔහු තුළට පිඹින විට, ඔබලා ඔහුට සුජූද් කර වැටෙනු." 15:29; 38:72
- = එවිට මලායිකාවෝ සියල්ලෝම එක්ව සුජූද් කළහ. 15:30; 38:73
- = (අල්ලාහ්) පැවසීය: "එසේ නම් එයින් පිටවී යනු. නියත වශයෙන්ම නුඹ ශාප ලත් අයෙකි." 15:34; 38:77
- = (ඉබ්ලීස්) පැවසීය: "මාගේ දෙවියනි, එසේ නම් ඔවුන් නැවත නඟිනු ලබන දිනය දක්වා මට කල් දෙනු මැනව." 15:36; 38:79
- = (අල්ලාහ්) පැවසීය: "එසේ නම් නියත වශයෙන්ම නුඹ කල් දෙනු ලැබූවන් අතර සිටින්නෙහිය." 15:37; 38:80
- = නියමිත කාලයේ දිනය දක්වා." 15:38; 38:81
- = ඔවුන් අතරින් නුඹගේ තෝරාගත් දාසයන් හැර. 15:40; 38:83
- = නියත වශයෙන්ම භක්තිවන්තයෝ උද්‍යාන හා දිය උල්පත් අතර වන්නෝය. 15:45; 51:15
- = ඔහු පැවසීය: "එසේ නම් ඔබගේ කාර්යය කුමක්ද, අහෝ දූතයිනි?" 15:57; 51:31
- = ඔවුහු පැවසූහ: "අපි අපරාධකාරී ජනතාවක් වෙත එවනු ලැබූවෙමු." 15:58; 51:32
- = විශ්වාස කර තම විශ්වාසය අයුක්තිය සමඟ නොමිශ්‍ර කළ අය – ඔවුන්ට ආරක්ෂාව හිමි වේ. තවද ඔවුහු යහමග ලැබූවෝය. 16:42; 29:59
- = එවිට ඔවුන් අප ඔවුන්ට ලබා දුන් දේ ප්‍රතික්ෂේප කරති. එබැවින් ඔබලා විඳගනු. නුඹලා ඉතා ඉක්මනින් දැන ගනු ඇත. 16:55; 30:34
- = ඉන්පසු ඔහු (තවත්) මාර්ගයක් අනුගමනය කළේය. 18:89; 18:92
- = පාරාවෝ වෙත යනු. නියත වශයෙන්ම ඔහු ඉක්මවා ගොස් ඇත. 20:24; 79:17
- = තවද ඔවුහු තම ලිංගික අවයව ආරක්ෂා කරන්නෝය. 23:5; 70:29
- = තම භාර්යාවන් හෝ තම දකුණත් හිමිකම් ඇති අය හැර – එවිට නියත වශයෙන්ම ඔවුන් දොස් නොකියනු ලබන්නෝය. 23:6; 70:30
- = එහෙත් ඊට ඔබ්බෙන් සොයන අය – ඔවුන්ම ඉක්මවා යන්නෝය. 23:7; 70:31
- = තවද ඔවුහු තම විශ්වාසයන් හා ගිවිසුම් ආරක්ෂා කරන්නෝය. 23:8; 70:32
- = ඔහු පැවසීය: "මාගේ දෙවියනි, ඔවුන් මා ප්‍රතික්ෂේප කළ බැවින් මට උපකාර කරනු මැනව." 23:26; 23:39
- = තා, සීන්, මීම්. 26:1; 28:1
- = මේවා පැහැදිලි ග්‍රන්ථයේ වදන් වේ. 26:2; 28:2
- = නියත වශයෙන්ම එහි සංඥාවක් ඇත. එහෙත් ඔවුන්ගෙන් බහුතරයක් විශ්වාස කළවුන් නොවීය. 26:8; 26:67; 26:103; 26:121; 26:174; 26:190
- = තවද නියත වශයෙන්ම නුඹගේ දෙවියන් – ඔහුම සර්වබලධාරී හා අති දයාන්විතය. 26:9; 26:68; 26:104; 26:122; 26:140; 26:159; 26:175; 26:191
- = තවද අපි අනෙක් අය ගිල්වා දැමුවෙමු. 26:66; 37:82
- = නියත වශයෙන්ම මම ඔබලාට විශ්වාසවන්ත දූතයෙක් වෙමි. 26:107; 26:125; 26:143; 26:162; 26:178
- = එබැවින් ඔබලා අල්ලාහ්ට බිය වනු. තවද මට කීකරු වනු. 26:108; 26:110; 26:126; 26:131; 26:144; 26:150; 26:163; 26:179
- = තවද මම ඒ සඳහා ඔබලාගෙන් කිසිදු වේතනයක් ඉල්ලා නොසිටිමි. මාගේ වේතනය ලෝකවාසීන්ගේ දෙවියන් වෙත පමණි. 26:109; 26:127; 26:145; 26:164; 26:180
- = උද්‍යාන හා දිය උල්පත් අතර. 26:147; 44:52
- = ඔවුහු පැවසූහ: "නුඹ මන්ත්‍රණයට ලක් වූවන් අතර සිටින්නෙහිය." 26:153; 26:185
- = ඔහුගේ බිරිඳ හැර – අපි ඇය පසුපසින් ඉතිරි වූවන් අතර සිටින බවට තීරණය කළෙමු. 26:171; 37:135
- = ඉන්පසු අපි අනෙක් අය විනාශ කළෙමු. 26:172; 37:136
- = තවද අපි ඔවුන් මත (ගල්) වර්ෂාවක් ඇද හෙළුවෙමු. එවිට අනතුරු ඇඟවූවන්ට එම වර්ෂාව කෙතරම් නරකද! 26:173; 27:58
- = එසේනම් ඔවුහු අපගේ දඬුවම ඉක්මන් කරවන්නට අවශ්‍ය වෙතිද? 26:204; 37:176
- = ඔවුහු සලාතය පවත්වති. සකාත් ද පවතිති. තවද ඔවුහු මතු ලොව ගැන නිසැකව විශ්වාස කරති. 27:3; 31:4
- = තවද (සිහි කරනු) ඔහු ඔවුන්ව කැඳවා "නුඹලා පැවසූ මාගේ 'හවුල්කරුවන්' කොහිද?" යනුවෙන් පවසන දිනය. 28:62; 28:74
- = තවද අපගේ මුතුන් මිත්තන්? 37:17; 56:48
- = තවද ඔවුන් එකිනෙකා දෙසට හැරී අසා විචාර කර ගනිති. 37:27; 52:25
- = එහෙත් (ඔවුහු) අල්ලාහ්ගේ තෝරාගත් දාසයෝය. 37:40; 37:74; 37:128; 37:160
- = නෙක් භෝගවල උද්‍යානවල. 37:43; 56:12
- = තවද අපි ඔහු සඳහා පසු පරම්පරාවන් අතර (යහපත් කීර්තියක්) ඉතිරි කළෙමු: 37:78; 37:108; 37:129
- = නියත වශයෙන්ම අපි යහපත් කරන්නන්ට මෙසේ ප්‍රතිඵල දෙමු. 37:80; 37:121; 37:131; 77:44
- = නියත වශයෙන්ම ඔහු අපගේ විශ්වාසවන්ත දාසයන් අතර සිටියේය. 37:81; 37:111; 37:132
- = ඔබලාට කුමක් වී ඇත්ද? ඔබලා විනිශ්චය කරන්නේ කෙසේද? 37:154; 68:36
- = මෙය ලෝකවාසීන්ට අවවාදයක් මිස අන් කිසිවක් නොවේ. 38:87; 81:27
- = ග්‍රන්ථයේ පහළ කිරීම අල්ලාහ්ගෙනි – සර්වබලධාරී, මහා ප්‍රඥාවන්තයාගෙනි. 39:1; 45:2; 46:2
- = හා, මීම්. 40:1; 41:1; 42:1; 43:1; 44:1; 45:1; 46:1
- = පැහැදිලි ග්‍රන්ථය මත දිවුරුම්. 43:2; 44:2
- = එබැවින් ඔවුන්ට ඔවුන්ගේ පොරොන්දු වූ දිනය හමු වන තෙක් ඔවුන් නිෂ්ඵල කථා හා ක්‍රීඩාවන්හි ගිලී සිටීමට ඉඩ හරිනු. 43:83; 70:42
- = (ඔවුන්ට පවසනු ඇත): "නුඹලා කරමින් සිටි දේ නිසා සතුටින් අනුභව කරනු. තවද පානය කරනු." 52:19; 77:43
- = එසේත් නැතිනම් නුඹ ඔවුන්ගෙන් වේතනයක් ඉල්ලන්නෙහිද? එවිට ඔවුහු නයකින් බර වී සිටිති. 52:40; 68:46
- = එසේත් නැතිනම් ඔවුන් වෙත අදෘශ්‍යමාන දැනුම ඇත්ද? එවිට ඔවුහු ලියති. 52:41; 68:47
- = එවිට මාගේ දඬුවම හා අනතුරු ඇඟවීම් කෙතරම්ද! 54:16; 54:21; 54:30
