- මෙලොව ජීවිතයේ උපමාව වන්නේ අපි අහසින් වැසි වතුර පහළ කළ අවස්ථාව වැනි ය; එවිට පොළොවේ පැළ ඒ සමඟ මිශ්‍ර විය... (مَثَلُ الْحَيَاةِ الدُّنْيَا كَمَاءٍ أَنزَلْنَاهُ مِنَ السَّمَاءِ فَاخْتَلَطَ بِهِ نَبَاتُ الْأَرْضِ) 10:24; 18:45
- එය (නැව) තුළට සෑම ජාතියකින්ම යුගල යුගල වශයෙන් හා ඔබගේ පවුලේ අයව (රැගෙන යන්න) - නමුත් කලින් විධානය ලැබූ අය හැර... (فِيهَا مِن كُلٍّ زَوْجَيْنِ اثْنَيْنِ وَأَهْلَكَ إِلَّا مَن سَبَقَ عَلَيْهِ الْقَوْلُ) 11:40; 23:27
- මම ඔබට නොකියමි, මා සතුව අල්ලාහ්ගේ නිධානයන් ඇති බවත්, මම අදෘශ්‍යමාන දේ නොදනිමි, තවද මම නොකියමි... (لَّا أَقُولُ لَكُمْ عِندِي خَزَائِنُ اللَّهِ وَلَا أَعْلَمُ الْغَيْبَ وَلَا أَقُولُ) 6:50; 11:31
- නිසැකවම අල්ලාහ් මිනිසුන්ට අනුග්‍රහය ඇති තැනැත්තා ය; නමුත් බොහෝ මිනිසුන් කෘතවේදී නොවෙති. (إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ) 2:243; 40:61
- ඔවුන්ගේ පරමාධිපතිගේ සංඥාවන්ගෙන් කිසිදු සංඥාවක් ඔවුන් වෙත නොඑළඹුණේ ය, ඔවුන් ඒවායින් ඉවතට හැරී ගියේ හැර. (وَمَا تَأْتِيهِم مِّنْ آيَةٍ مِّنْ آيَاتِ رَبِّهِمْ إِلَّا كَانُوا عَنْهَا مُعْرِضِينَ) 6:4; 36:46
- තවද කිසිදු ආත්මයක් තවත් ආත්මයක් වෙනුවෙන් කිසිවක් ප්‍රතික්ෂේප නොකරන, තවද එයින් කිසිදු නිර්දේශයක් පිළි නොගන්නා එම දිනය ගැන බිය වන්න. (وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا) 2:48; 2:123
- නිසැකවම ඔබට මළවුන්ට ඇසීමට කළ නොහැකි අතර, ඔවුන් පිටුපා යන විට බිහිරි අයට ඇසීමට ද කළ නොහැක. (إِنَّكَ لَا تُسْمِعُ الْمَوْتَى وَلَا تُسْمِعُ الصُّمَّ الدُّعَاءَ إِذَا وَلَّوْا مُدْبِرِينَ) 27:80; 30:52
- ඔබට මළ සතා, ලේ, ඌරු මස් සහ අල්ලාහ් නොවන වෙනත් අයෙකුගේ නමින් මරා දැමූ දේ තහනම් කර ඇත. (حُرِّمَتْ عَلَيْكُمُ الْمَيْتَةُ وَالدَّمُ وَلَحْمُ الْخِنزِيرِ وَمَا أُهِلَّ لِغَيْرِ اللَّهِ بِهِ) 5:3; 16:115
- අහස් හා පොළොවේ ඇති සියල්ල අල්ලාහ්ව උත්කර්ෂයට නංවයි; තවද ඔහු සර්වබලධාරී, ප්‍රඥාවන්තයා ය. (سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَهُوَ الْعَزِيزُ الْحَكِيمُ) 59:1; 61:1
- එහෙත් ඊට පසු පසුතැවී තමන්ව (හැසිරීම්) ප්‍රතිසංස්කරණය කළ අය හැර. නිසැකවම අල්ලාහ් ක්ෂමාශීලී, දයාන්විතය. (إِلَّا الَّذِينَ تَابُوا مِن بَعْدِ ذَلِكَ وَأَصْلَحُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ) 3:89; 24:5
- (එය) ඔවුන්ගේ පරමාධිපති වෙතින් අනාගතවක්තෘවරුන්ට (ලැබුණි); අපි ඔවුන් අතර කිසිවෙකු වෙන්කර නොසලකමු, තවද අපි ඔහුට යටත් වන්නෝ (මුස්ලිම්වරු) වෙමු. (النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ) 2:136; 3:84
- ඔබගේ පරමාධිපති වෙතින් (එවන ලද්දේ) ඔබට පෙර කිසිදු අනතුරු ඇඟවීමක් නොපැමිණි ජනතාවකට ඔබ අනතුරු ඇඟවීම සඳහා ය, ඔවුන්... (مِّن رَّبِّكَ لِتُنذِرَ قَوْمًا مَّا أَتَاهُم مِّن نَّذِيرٍ مِّن قَبْلِكَ لَعَلَّهُمْ) 28:46; 32:3
- අහෝ නබි (අනාගතවක්තෘ)වරයා, ප්‍රතික්ෂේප කරන්නන් හා කපටි ප්‍රතික්ෂේපකයන් සමඟ සටන් කරන්න; ඔවුන් කෙරෙහි දැඩි වන්න. ඔවුන්ගේ වාසස්ථානය නිරය (ජහන්නම්) ය; එම නරකම ස්ථානය වේ! (يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ) 9:73; 66:9
- නිසැකවම ඔබගේ පරමාධිපති, උත්ථාන දිනයේ ඔවුන් අතර ඔවුන් මතභේදයට පත් වූ දේ ගැන තීන්දු කරනු ඇත. (إِنَّ رَبَّكَ يَقْضِي بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 10:93; 45:17
- ඔහු කීවේය: මාගේ පරමාධිපතිනි, මට සංඥාවක් තබනු මැනව. ඔහු කීවේය: ඔබගේ සංඥාව නම්, ඔබ දින තුනක් මිනිසුන් සමඟ කතා නොකිරීමයි. (قَالَ رَبِّ اجْعَل لِّي آيَةً قَالَ آيَتُكَ أَلَّا تُكَلِّمَ النَّاسَ) 3:41; 19:10
- එබැවින් ඔබගේ මුහුණ ශුද්ධ වූ පල්ලිය (මස්ජිදුල් හරාම්) දෙසට හරවනු. තවද ඔබ කොතැනක සිටියත්, ඔබගේ මුහුණු එය දෙසට හරවනු. (فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ) 2:144; 2:150
- අහෝ ඉස්රායිල් දරුවෙනි, මා ඔබට ලබා දුන් මාගේ ආශිර්වාදය ද, තවද මා ඔබව ලෝකවාසීන්ට වඩා උසස් කළ බව ද සිහි කරන්න. (يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ) 2:47; 2:122
- තරබාරු එළදෙනුන් හත්දෙනෙක්, කෙට්ටු එළදෙනුන් හත්දෙනෙක් ඒවා කා දමයි; කොළ පැහැති කරල් හත්දෙනෙක් හා අනෙක් ඒවා වියලි... (سَبْعَ بَقَرَاتٍ سِمَانٍ يَأْكُلُهُنَّ سَبْعٌ عِجَافٌ وَسَبْعَ سُنبُلَاتٍ خُضْرٍ وَأُخَرَ يَابِسَاتٍ) 12:43; 12:46
- සෑම ජන කොට්ඨාසයකටම නියමිත කාලයක් ඇත; ඔවුන්ගේ නියමිත කාලය පැමිණි විට, ඔවුන්ට එය මොහොතක් ප්‍රමාද කිරීමට හෝ ඉක්මන් කිරීමට නොහැකි වනු ඇත. (وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49
- (එය) අල්ලාහ් නොවන වෙනත් අයෙකුගේ නමින් මරා දමන ලද්දක් වන අතර, නමුත් යමෙක් (කුසගින්නෙන්) බල කරනු ලැබුවේ නම්, කැරැලිකාර නොවී හා සීමාව ඉක්මවා නොයා, එවිට... (أُهِلَّ لِغَيْرِ اللَّهِ بِهِ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَإِنَّ) 6:145; 16:115
