- එය අදෘශ්යමාන පුවත් අතුරින් වන අතර එය අපි ඔබ වෙත වහි කරන්නෙමු; ඔවුන් තීරණය කරන විට ඔබ ඔවුන් සමඟ නොසිටියෙහිය. (ذَلِكَ مِنْ أَنبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ لَدَيْهِمْ إِذْ) 3:44; 12:102
- ඔබගේ පරමාධිපතිගෙන් ඔබ අතුරින්ම එක් මිනිසෙකු මගින් ඔබ වෙත අවවාදයක් පැමිණියේද යන්න ගැන ඔබ පුදුම වෙනවාද, ඔහු ඔබට අවවාද කිරීමට? (أَوَعَجِبْتُمْ أَن جَاءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَى رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ) 7:63; 7:69
- පවසනු: "නිසැකවම, අල්ලාහ් හැර ඔබ යාච්ඤා කරන අයට නමස්කාර කිරීමෙන් මට තහනම් කර ඇත." (قُلْ إِنِّي نُهِيتُ أَنْ أَعْبُدَ الَّذِينَ تَدْعُونَ مِن دُونِ اللَّهِ) 6:56; 40:66
- ඔවුන්ගේ භාර්යාවන් හෝ ඔවුන්ගේ දකුණු අත් සන්තකයේ ඇති අය හැර, මන්ද ඔවුන් නින්දා නොකළ යුත්තෝය. (إِلَّا عَلَى أَزْوَاجِهِمْ أَوْ مَا مَلَكَتْ أَيْمَانُهُمْ فَإِنَّهُمْ غَيْرُ مَلُومِينَ) 23:6; 70:30
- අල්ලාහ් රාත්රිය දවාලට ඇතුළත් කරන නිසාත්, දවාල රාත්රියට ඇතුළත් කරන නිසාත්ය. (بِأَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ) 22:61; 31:29
- ගින්න, තවද ඔහු තම පවුලේ අයට මෙසේ පැවසීය: "රැඳී සිටින්න, මම ගින්නක් දුටුවෙමි, සමහර විට මම එයින් ඔබට යමක් ගෙනෙන්නෙමි." (نَارًا فَقَالَ لِأَهْلِهِ امْكُثُوا إِنِّي آنَسْتُ نَارًا لَّعَلِّي آتِيكُم مِّنْهَا) 20:10; 28:29
- ඔහු පැවසීය: "මම ඔහුට වඩා උතුම්ය; ඔබ මාව ගින්නෙන් මැව්වෙහිය, තවද ඔහුව මැටියෙන් මැව්වෙහිය." (قَالَ أَنَا خَيْرٌ مِّنْهُ خَلَقْتَنِي مِن نَّارٍ وَخَلَقْتَهُ مِن طِينٍ) 7:12; 38:76
- තවද ඔවුන්ට පවසනු ලැබූ විට: "අල්ලාහ් පහළ කළ දෙය වෙතට සහ දූතයා වෙතට එන්න." (وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَى مَا أَنزَلَ اللَّهُ وَإِلَى الرَّسُولِ) 4:61; 5:104
- තවද ඔබ ඔවුන් ගැන ශෝක නොවන්න, තවද ඔවුන් කරන කුමන්ත්රණ නිසා පීඩාවට පත් නොවන්න. (وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِّمَّا يَمْكُرُونَ) 16:127; 27:70
- අල්ලාහ් ඔබට යම් හානියක් සිදු කළහොත්, ඔහු හැර අන් කිසිවෙකුට එය ඉවත් කළ නොහැක, තවද ඔහු. (وَإِن يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلَا كَاشِفَ لَهُ إِلَّا هُوَ وَإِن) 6:17; 10:107
- ඔවුන්ට පෙර පරම්පරාවන් තම නිවෙස් තුළ සැරිසැරූහ; නිසැකවම, එහි සංඥා ඇත. (قَبْلَهُم مِّنَ الْقُرُونِ يَمْشُونَ فِي مَسَاكِنِهِمْ إِنَّ فِي ذَلِكَ لَآيَاتٍ) 20:128; 32:26
- තවද අපි ඔවුන්ගේ සිත් මත ආවරණ තැබුවෙමු, එවිට ඔවුන්ට එය වටහා ගත නොහැකි වනු ඇත, තවද ඔවුන්ගේ කන්වල බිහිරි බවක්, තවද ඔවුන්. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن) 6:25; 18:57
- ඔවුන්ගේ දූතයෝ පැහැදිලි සාධක සමඟ ඔවුන් වෙත පැමිණියහ, නමුත් අල්ලාහ් ඔවුන්ට අයුතුකම් කරන්නෙකු නොවීය, නමුත් ඔවුන් තමන්ටම අයුතුකම් කර ගත්හ. (رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ) 9:70; 30:9
- තවද පොළොවෙහි, තවද අල්ලාහ් හැර ඔබට කිසිදු ආරක්ෂකයෙකු හෝ උපකාරකයෙකු නැත. (وَالْأَرْضِ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 42:31
- ඉන්පසු ඔබ අදෘශ්යමාන හා ප්රකට දෑ දන්නා තැනැත්තා වෙතට නැවත යවනු ලබන්නෙහුය, එවිට ඔහු ඔබ කළ දෑ ගැන ඔබට දන්වන්නේය. (ثُمَّ تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 62:8
- රාත්රිය, එහි ඔබ විවේක ගැනීමට, තවද දවාල, ඔබ දැකීමට; නිසැකවම, එහි චින්තනය කරන ජනයාට සංඥා ඇත. (اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ فِي ذَلِكَ لَآيَاتٍ لِّقَوْمٍ) 10:67; 27:86
- තවද ඔබගේ පරමාධිපතිගෙන් ඔබ වෙත පහළ කරන ලද දෙය ඔවුන්ගෙන් බොහෝ දෙනෙකුගේ කැරැල්ල හා ප්රතික්ෂේප කිරීම තවත් වැඩි කරන්නේය. (وَلَيَزِيدَنَّ كَثِيرًا مِّنْهُم مَّا أُنزِلَ إِلَيْكَ مِن رَّبِّكَ طُغْيَانًا وَكُفْرًا) 5:64; 5:68
- ඔහු පැවසීය: "මාගේ ජනයිනි! ඔබ කුමක් සිතන්නහුද? මම මගේ පරමාධිපතිගෙන් පැහැදිලි සාධකයක් මත සිටින්නෙම් නම් සහ ඔහු මට ලබා දී ඇත්නම්." (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي وَآتَانِي) 11:28; 11:63
- තවද ඔවුන් පවසති: "ඔහුගේ පරමාධිපතිගෙන් ඔහු වෙත සලකුණක් පහළ කරනු ලැබුවේ මන්ද නොවේද?" පවසනු: "නිසැකවම." (وَيَقُولُونَ لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ فَقُلْ إِنَّمَا) 10:20; 29:50
- අල්ලාහ්ගෙන් නැවත පැමිණීමක් නැති දිනයක් පැමිණීමට පෙර. (مِن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا مَرَدَّ لَهُ مِنَ اللَّهِ) 30:43; 42:47
- එය අල්ලාහ්ගේ අනුග්රහයයි, ඔහු තමා කැමති තැනැත්තාට එය දෙන්නේය, තවද අල්ලාහ් මහා අනුග්රහයෙන් යුත් අයෙකි. (ذَلِكَ فَضْلُ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 62:4
- තවද නිසැකවම, පශු සම්පතෙහි ඔබට පාඩමක් ඇත; අපි ඔවුන්ගේ කුසෙහි ඇති දෙයින් ඔබට පානය කරවන්නෙමු. (وَإِنَّ لَكُمْ فِي الْأَنْعَامِ لَعِبْرَةً نُّسْقِيكُم مِّمَّا فِي بُطُونِهِ) 16:66; 23:21
- එය ඔවුන්ගේ පරමාධිපතිගෙන් සත්යයක් බවත්, අල්ලාහ් ඔවුන් කරන දෑ ගැන නොසලකන්නෙකු නොවන බවත්. (أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ) 2:144; 2:149
