- තවද අල්ලාහ් හැර ඔබට කිසිදු ආරක්ෂකයෙකු හෝ උපකාරකයෙකු නැත. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- නිසැකවම, මම ඔවුන්ගේ පව් ඉවත් කරන්නෙමි, තවද ඔවුන්ව යටින් ගංගා ගලා යන ස්වර්ග උයනට ඇතුළත් කරන්නෙමි. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- අපි ඔවුන්ව යටින් ගංගා ගලා යන ස්වර්ග උයනට ඇතුළත් කරන්නෙමු, එහි ඔවුන් සදාකාලිකව සිටින්නෝය. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- ඔබගේ පරමාධිපති තම මාර්ගයෙන් යමෙකු මංමුලා වූයේද යන්න වඩාත් හොඳින් දනී, තවද ඔහු වඩාත් හොඳින් දනී. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- ඔබ අදෘශ්යමාන හා ප්රකට දෑ දන්නා තැනැත්තා වෙතට නැවත යවනු ලබන්නෙහුය, එවිට ඔහු ඔබ කළ දෑ ගැන ඔබට දන්වන්නේය. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- ඔවුන් ඔබේ පුතුන් මරා දැමූහ, තවද ඔබේ කාන්තාවන් ජීවත්ව තැබූහ; එහි ඔබගේ පරමාධිපතිගෙන් මහත් පරීක්ෂාවක් විය. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- නිසැකවම, ඔබගේ පරමාධිපති තම මාර්ගයෙන් යමෙකු මංමුලා වන්නේද යන්න වඩාත් හොඳින් දනී, තවද ඔහු. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- අල්ලාහ්, අහස්හි ඇති දේ සහ පොළොවෙහි ඇති දේ උන්වහන්සේ සතුය. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- ඔබට පෙර පැවති ජනයා අතර, ජින්නුන්ගෙන් සහ මිනිසුන්ගෙන්. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- අල්ලාහ්ට නමස්කාර කරන්න, ඔහු හැර ඔබට වෙනත් දෙවියෙක් නැත, ඔබ බිය නොවන්නේද? (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- තවද අපි ඔවුන්ගේ සිත් මත ආවරණ තැබුවෙමු, එවිට ඔවුන්ට එය වටහා ගත නොහැකි වනු ඇත, තවද ඔවුන්ගේ කන්වල බිහිරි බවක්. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- ඔහු උත්ථාන දිනයේදී ඔවුන් අතර මතභේදයට පත් වූ දෙය සම්බන්ධයෙන් විනිශ්චය කරන්නේය. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- ඔහු පැවසීය: "මාගේ ජනයිනි! ඔබ කුමක් සිතන්නහුද? මම මගේ පරමාධිපතිගෙන් පැහැදිලි සාධකයක් මත සිටින්නෙම් නම්?" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- එයට හේතුව නම් ඔබගේ අත් ඉදිරියට යැවූ දෙයයි, තවද අල්ලාහ් තම දාසයන්ට අපරාධකාරයෙකු නොවේ. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- ඔවුන්ට මෙලොවෙහි අපකීර්තියක් ඇත, තවද ඔවුන්ට මතු ලොවෙහි මහත් දඬුවමක් ඇත. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- අහස්හි ඇති දේ සහ පොළොවෙහි ඇති දේ, තවද අල්ලාහ් ආරක්ෂකයෙකු ලෙස ප්රමාණවත් වන්නේය. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- විශ්වාස කර යහපත් ක්රියා කළ අය හැර; ඔවුන්ට නොකැඩෙන ත්යාගයක් ඇත. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- ඔබ නොදන්නා දෙයක් මට හවුල්කරුවෙකු කර නොගන්නා ලෙස; ඔවුන් දෙදෙනාට කීකරු නොවන්න. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- නිසැකවම, මෙය අවවාදයකි; එමනිසා කැමති තැනැත්තෙකු තම පරමාධිපති වෙත මාර්ගයක් ගනීවා. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- තවද යමෙක් කෘතඥ වන්නේද, ඔහු කෘතඥ වන්නේ තමාටමය; තවද යමෙක් කෘතඥ නොවන්නේද. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- යම් අයෙක් සලාතය ස්ථාපිත කරති, සකාත් දෙති, තවද මතු ලොව ගැන ස්ථිර විශ්වාසයක් ඇත. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- ඉබ්රාහිම්, ඉස්මයිල්, ඉස්හාක්, යාකූබ් සහ ගෝත්රයන්ට, තවද මූසා සහ ඊසාට ලබා දුන් දෙයට. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- කණ්ඩායම් වශයෙන්, ඔවුන් එය වෙත පැමිණෙන තෙක්, තවද එහි දොරටු විවෘත කරනු ලැබේ, තවද එහි ආරක්ෂකයෝ ඔවුන්ට පවසති. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- අල්ලාහ් ඔබගේ දිවුරුම්වල නිෂ්ඵල දෑ සම්බන්ධයෙන් ඔබට දඬුවම් නොකරන්නේය, නමුත් ඔබට දඬුවම් කරන්නේ එම දෙය සම්බන්ධයෙනි. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- දයාව, ඔවුන් එයින් සතුටු වෙති, තවද ඔවුන්ගේ අත් ඉදිරියට යැවූ දෙය නිසා ඔවුන්ට යම් අයහපතක් සිදු වුවහොත්. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- යටින් ගංගා ගලා යන ස්වර්ග උයන්, එහි ඔවුන් සදාකාලික වන්නෝය, තවද කර්මකරුවන්ගේ ත්යාගය කොතරම් උතුම්ද! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- අල්ලාහ් අහස්හි ඇති දේ සහ පොළොවෙහි ඇති දේ දනී, තවද අල්ලාහ්. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- අල්ලාහ්ට කීකරු වන්න, තවද දූතයාට කීකරු වන්න; නමුත් ඔබ ඉවතට හැරුනහොත්, ඔහුගේ වගකීම. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- ඔවුන්ට ඔවුන්ගේ පරමාධිපති සමීපයෙහි ඔවුන්ගේ ත්යාගය ඇත, තවද ඔවුන්ට කිසිදු බියක් නැත, තවද ඔවුන්. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- තවද ඔවුන් පැවසූහ: "අප ඇටකටු සහ දූවිලි බවට පත් වූ විට, අප නව මැවීමක් ලෙස නැවත උත්ථාන කරනු ලබන්නෙමුද?" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- තවද ඔවුන් තමන්ට අල්ලාහ් හැර කිසිදු ආරක්ෂකයෙකු හෝ උපකාරකයෙකු සොයා නොගනිති. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "ඔබ කොපමණ කාලයක් රැඳී සිටියෙහිද?" ඔහු පැවසීය: "මම එක් දිනක් හෝ දිනයක කොටසක් රැඳී සිටියෙමි." ඔහු පැවසීය. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- උත්ථාන දිනය දක්වා සදාකාලිකව, අල්ලාහ් හැර ඔබට ගෙන ඒමට හැකි දෙවියෙකු කවුද? (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- යමෙක් යහපත් ක්රියා කරන්නේද, පුරුෂයෙක් හෝ ස්ත්රියක්, තවද ඔහු විශ්වාසවන්තයෙක් වේ. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- යම් අයෙක් අල්ලාහ්ගේ මාර්ගයෙන් අන් අයව වළක්වති, තවද එය වක්ර කිරීමට අපේක්ෂා කරති, තවද ඔවුන් මතු ලොව ගැන. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- ඔබ කැමති තැන කන්න, නමුත් මෙම ගසට නොළඟින්න, එවිට ඔබ අපරාධකාරයන්ගෙන් කෙනෙකු වන්නෙහුය. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- පවසනු: "මාගේ ජනයිනි! ඔබ ඔබගේ ස්ථානයෙහි ක්රියා කරන්න, මමත් ක්රියා කරන්නෙමි, එවිට ඔබ ඉක්මනින් දැන ගන්නෙහුය." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- නිසැකවම, අලාභයට පත් වූවෝ නම් උත්ථාන දිනයේදී තමන්ව සහ තම පවුල්වල අයව අලාභයට පත් කර ගත් අයයි, සැබැවින්ම. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- යමෙක් මඟ පෙන්වනු ලැබේද, ඔහු මඟ පෙන්වනු ලබන්නේ තමාටමය; තවද යමෙක් මංමුලා වන්නේද, ඔහු මංමුලා වන්නේ තමාටමය; තවද. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- තවද ප්රතික්ෂේප කළ අය පවසති: "ඔහුගේ පරමාධිපතිගෙන් ඔහු වෙත සලකුණක් පහළ කරනු ලැබුවේ මන්ද නොවේද?" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- යමෙක් ඔබට රාත්රිය සැකසූවේ එහි ඔබ විවේක ගැනීමටත්, දවාල ඔබ දැකීමටත්ය, නිසැකවම. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- කිසිදු මිලදී ගැනීමක් හෝ මිතුරුකමක් නැති දිනයක් පැමිණීමට පෙර. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- ඔවුන්ගේ සහකරුට කිසිදු උමතුවක් නැති බව ඔවුන් සිතනු පිණිස; ඔහු පැහැදිලි අවවාද කරන්නෙකු පමණි. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- එහි ඔවුන් සදාතනිකව සිටින්නෝය, දඬුවම ඔවුන්ට සැහැල්ලු නොකරනු ලබන්නේය, තවද ඔවුන්ට කල් නොදෙනු ලබන්නේය. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- අපි ඔවුන්ගෙන් සමහරෙකුට වින්දනයක් ලෙස ලබා දුන් දේ වෙත ඔබගේ ඇස් දිගු නොකරන්න. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- තවද මිනිසුන්ට ඔවුන්ගේ භාණ්ඩවලින් අඩු නොකරන්න, තවද පොළොවෙහි අපරාධ නොකරන්න. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- තවද ඔහු උපත ලද දිනයෙහිද, ඔහු මිය යන දිනයෙහිද, තවද ඔහු ජීවමානව නැවත උත්ථාන කරනු ලබන දිනයෙහිද ඔහුට ශාන්තිය වේවා. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- මාගේ ජනයිනි! ඔබ ඔබගේ ස්ථානයෙහි ක්රියා කරන්න, මමත් ක්රියා කරන්නෙමි, එවිට ඔබ ඉක්මනින් දැන ගන්නෙහුය කවුරුන්ද යන්න. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- තවද කිසිදු දූතයෙකුට අල්ලාහ්ගේ අවසරය නොමැතිව සලකුණක් ගෙන ඒමට නොහැකි විය. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- ඉන්පසු සෑම ආත්මයක්ම තමා උපයා ගත් දෙය සම්පූර්ණයෙන් ගෙවනු ලබන්නේය, තවද ඔවුන්ට අයුතුකම් නොකරනු ලබන්නේය. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- පුරුෂයෙක් හෝ ස්ත්රියක්, තවද ඔහු විශ්වාසවන්තයෙක් වේ, එවිට ඔවුහු ස්වර්ගයට ඇතුළත් වන්නාහුය. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- ඔහු දරුවෙකු ගෙන නැත, තවද පාලනයෙහි ඔහුට කිසිදු හවුල්කරුවෙකු නැත. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- තවද අල්ලාහ් යමෙකුට මඟ පෙන්වන්නේද, ඔහු මඟ පෙන්වනු ලැබූ තැනැත්තාය; තවද යමෙකුව ඔහු මංමුලා කරන්නේද. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- ඔවුන් ඔබට උපමා ගෙන එන ආකාරය බලන්න, එවිට ඔවුන් මංමුලා වූහ, තවද ඔවුන්ට මාර්ගයක් සොයාගත නොහැකි විය. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- පවසනු: "මම මගේ පරමාධිපතිට අකීකරු වුවහොත්, මහත් දිනයේ දඬුවම ගැන මම බිය වෙමි." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- ඔවුන් දෙදෙනාගේ ලජ්ජා ස්ථාන ඔවුන්ට හෙළි විය, තවද ඔවුහු ස්වර්ගයේ කොළ වලින් තමන්ව ආවරණය කර ගැනීමට පටන් ගත්හ. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- තවද අල්ලාහ් හැර ඔබට හැකි අයව ආයාචනා කරන්න, ඔබ සත්යවාදීන් නම්. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
- පොළොවෙහි ඇති සියල්ල සහ ඊට සමාන තවත් ප්රමාණයක්, ඒ සමඟ ඔවුන් මිදීමට. (مَّا فِي الْأَرْضِ جَمِيعًا وَمِثْلَهُ مَعَهُ لِيَفْتَدُوا بِهِ مِنْ) 5:36; 39:47
- අපි ඔබට දුන් දෙය ශක්තිමත්ව ගන්න, තවද එහි ඇති දෙය මතක තබා ගන්න, එවිට ඔබ භක්තිවන්ත වන්නට පුළුවන. (خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ) 2:63; 7:171
- ඔබ එම අශෝභන ක්රියාව කරන්නෙහුද, එය ඔබට පෙර ලෝකවාසීන්ගෙන් කිසිවෙකුත් නොකළ දෙයක් වන අතර? (أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ) 7:80; 29:28
- තවද අහස්හි ඇති දේ සහ පොළොවෙහි ඇති දේ අල්ලාහ් සතුය, තවද අල්ලාහ්. (وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَانَ اللَّهُ) 4:126; 4:131
- ඔවුන් කළ පාපකර්ම ඔවුන්ව වට කර ගත්තේය, තවද ඔවුන් සමච්චලයට ලක් කළ දෙය ඔවුන්ව ආවරණය කළේය. (سَيِّئَاتُ مَا عَمِلُوا وَحَاقَ بِهِم مَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 16:34; 45:33
- ඔබ අතුරින්ම දූතයෙක්, ඔහු අපගේ වදන් ඔබට පාරායනය කරයි, ඔබව පවිත්ර කරයි, තවද ඔබට ග්රන්ථය හා ප්රඥාව උගන්වයි. (رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ) 2:151; 62:2
- එයින් උල්පත් දොළොසක් ගලා ගියේය; සෑම ජන කොට්ඨාසයක්ම තම පානීය ස්ථානය දැන සිටියේය. (مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ) 2:60; 7:160
- උපකල්පනය හැර, තවද නිසැකවම උපකල්පනය සත්යයට එරෙහිව කිසිදු ප්රයෝජනයක් නොදේ. (إِلَّا ظَنًّا إِنَّ الظَّنَّ لَا يُغْنِي مِنَ الْحَقِّ شَيْئًا) 10:36; 53:28
- එවිට මම ඔහුව පිළිසකර කළ විට, තවද මාගේ ආත්මයෙන් ඔහු තුළට පිඹින විට, ඔබ ඔහුට සුජූද් කර වැටෙන්න. (فَإِذَا سَوَّيْتُهُ وَنَفَخْتُ فِيهِ مِن رُّوحِي فَقَعُوا لَهُ سَاجِدِينَ) 15:29; 38:72
- මෙම ලෝකයේ යහපත් අවසානය කාටද? නිසැකවම, අපරාධකාරයෝ සාර්ථක නොවෙති. (مَن تَكُونُ لَهُ عَاقِبَةُ الدَّارِ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ) 6:135; 28:37
- අහස් හා පොළොව මැවූ තැනැත්තා ඔවුන් හා සමාන දෑ මැවීමට සමත්ය. (الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ قَادِرٌ عَلَى أَن يَخْلُقَ مِثْلَهُمْ) 17:99; 36:81
- විශ්වාසවන්ත පුරුෂයින්ට සහ විශ්වාසවන්ත ස්ත්රීන්ට, යටින් ගංගා ගලා යන ස්වර්ග උයන්, එහි ඔවුන් සදාකාලික වන්නෝය. (الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 9:72; 48:5
- තවද ඔබ ඔවුන්ගෙන් අසන්නේ නම්, අහස් හා පොළොව මැව්වේ කවුරුන්දැයි, ඔවුන් නිසැකවම "අල්ලාහ්" යැයි පවසනු ඇත; පවසනු. (وَلَئِن سَأَلْتَهُم مَّنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ) 31:25; 39:38
- තවද නිසැකවම, අපි මෙම කුර්ආනයෙහි මිනිසුන්ට සියලු ආකාර උපමා ගෙන ආවෙමු. (وَلَقَدْ ضَرَبْنَا لِلنَّاسِ فِي هَذَا الْقُرْآنِ مِن كُلِّ مَثَلٍ) 30:58; 39:27
- අපගේ දූතයෝ ලූත් වෙත පැමිණි විට, ඔහු ඔවුන් නිසා දුක් විය, තවද පීඩාවට පත් විය, තවද පැවසීය. (جَاءَتْ رُسُلُنَا لُوطًا سِيءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًا وَقَالَ) 11:77; 29:33
- තවද අපි මලායිකාවන්ට පැවසූ විට: "ආදම්ට සුජූද් කරන්න," එවිට ඔවුහු සුජූද් කළහ, නමුත් ඉබ්ලිස් හැර, ඔහු ප්රතික්ෂේප කළේය. (وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَى) 2:34; 20:116
- තවද පොළොව අපි පැතිරෙව්වෙමු, තවද එහි කඳු තැබුවෙමු, තවද එහි සියලු ආකාර අලංකාර දෑ වවන ලදි. (وَالْأَرْضَ مَدَدْنَاهَا وَأَلْقَيْنَا فِيهَا رَوَاسِيَ وَأَنبَتْنَا فِيهَا مِن كُلِّ) 15:19; 50:7
- ඔවුහු අල්ලාහ්ට ආයාචනා කළහ, ඔහු සඳහා ආගම පවිත්ර කර ගනිමින්, තවද ඔහු ඔවුන්ව ගොඩබිමට ගලවා ගත් විට. (دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ) 29:65; 31:32
- ඔවුන්ට උතුරන වතුරින් පානයක් ඇත, තවද ඔවුන් ප්රතික්ෂේප කළ නිසා වේදනාකාරී දඬුවමක් ඇත. (لَهُمْ شَرَابٌ مِّنْ حَمِيمٍ وَعَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْفُرُونَ) 6:70; 10:4
- අපි අල්ලාහ් හැර, අපට ප්රයෝජනයක් හෝ හානියක් නොකරන දෙයකට ආයාචනා කරන්නෙමුද? (أَنَدْعُو مِن دُونِ اللَّهِ مَا لَا يَنفَعُنَا وَلَا يَضُرُّنَا) 6:71; 10:106
- අල්ලාහ් අහස්හි ඇති දේ සහ පොළොවෙහි ඇති දේ දනී. (أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 5:97; 58:7
